WITH hashes AS (
SELECT 'nba_v1_forecasts' AS scope,count(*)::int AS rows,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY forecast_id),''),'UTF8')),'hex') AS sha256 FROM public.nba_decision_shadow_forecasts_v1 t
UNION ALL SELECT 'nba_v1_outcomes',count(*)::int,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY forecast_id),''),'UTF8')),'hex') FROM public.nba_decision_shadow_outcomes_v1 t
UNION ALL SELECT 'nba_v2_forecasts',count(*)::int,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY id),''),'UTF8')),'hex') FROM nba_v2_shadow.forecasts t
UNION ALL SELECT 'nba_v2_judgments',count(*)::int,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY cycle_id,forecast_id),''),'UTF8')),'hex') FROM nba_v2_shadow.judgments t
UNION ALL SELECT 'ncaab_calibration',count(*)::int,encode(sha256(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY id),''),'UTF8')),'hex') FROM public.ncaab_calibration_shadow_v1 t
UNION ALL SELECT 'nba_goat_frozen_fields',count(*)::int,encode(sha256(convert_to(coalesce(string_agg(jsonb_build_object('id',id,'model_version',model_version,'game_id',game_id,'generated_at',generated_at,'created_at',created_at,'commence_time',commence_time,'market',market,'team',team,'selection',selection,'line',line,'sportsbook',sportsbook,'odds',odds,'model_probability',model_probability,'implied_probability',implied_probability,'confidence',confidence,'edge',edge,'ev',ev,'projected_line',projected_line,'feature_snapshot',feature_snapshot,'prediction_origin',prediction_origin,'production_eligible',production_eligible,'recommended_pick',recommended_pick,'stake',stake,'model_role',model_role)::text,E'\n' ORDER BY id),''),'UTF8')),'hex') FROM public.prediction_history WHERE sport_key='basketball_nba' AND prediction_origin='CURRENT_ERA_SHADOW' AND feature_snapshot->>'goatProviderPolicy'='NBA_GOAT_ARCHIVE_SHADOW_V1')
SELECT transaction_timestamp() AS captured_at,jsonb_agg(hashes ORDER BY scope) AS evidence FROM hashes;
